SET LOCAL aidash.scope = 'deployment';
UPDATE "core_runs" SET "area_id" = (SELECT (SELECT s.id FROM core_areas AS s WHERE s.tenant = a.tenant AND s.home_node = a.home_node AND s.workspace_id = a.workspace_id AND s.agent_id = a.agent_id AND s.owner = a.owner ORDER BY CASE WHEN s.state IN ('active', 'running') THEN 0 WHEN s.state IN ('retained', 'recoverable') THEN 1 ELSE 2 END, (SELECT max(r.created_at) FROM core_runs AS q JOIN runs AS r ON r.id = q.run_id WHERE q.area_id = s.id) DESC NULLS LAST, s.id DESC LIMIT 1) FROM core_areas AS a WHERE a.id = core_runs.area_id), "generation" = (SELECT s.generation FROM core_areas AS s WHERE s.id = (SELECT (SELECT s.id FROM core_areas AS s WHERE s.tenant = a.tenant AND s.home_node = a.home_node AND s.workspace_id = a.workspace_id AND s.agent_id = a.agent_id AND s.owner = a.owner ORDER BY CASE WHEN s.state IN ('active', 'running') THEN 0 WHEN s.state IN ('retained', 'recoverable') THEN 1 ELSE 2 END, (SELECT max(r.created_at) FROM core_runs AS q JOIN runs AS r ON r.id = q.run_id WHERE q.area_id = s.id) DESC NULLS LAST, s.id DESC LIMIT 1) FROM core_areas AS a WHERE a.id = core_runs.area_id)), "sequence" = (SELECT s.next_sequence FROM core_areas AS s WHERE s.id = (SELECT (SELECT s.id FROM core_areas AS s WHERE s.tenant = a.tenant AND s.home_node = a.home_node AND s.workspace_id = a.workspace_id AND s.agent_id = a.agent_id AND s.owner = a.owner ORDER BY CASE WHEN s.state IN ('active', 'running') THEN 0 WHEN s.state IN ('retained', 'recoverable') THEN 1 ELSE 2 END, (SELECT max(r.created_at) FROM core_runs AS q JOIN runs AS r ON r.id = q.run_id WHERE q.area_id = s.id) DESC NULLS LAST, s.id DESC LIMIT 1) FROM core_areas AS a WHERE a.id = core_runs.area_id)) + (SELECT count(*) FROM core_runs AS o JOIN core_areas AS oa ON oa.id = o.area_id WHERE oa.id <> (SELECT s.id FROM core_areas AS s WHERE s.tenant = oa.tenant AND s.home_node = oa.home_node AND s.workspace_id = oa.workspace_id AND s.agent_id = oa.agent_id AND s.owner = oa.owner ORDER BY CASE WHEN s.state IN ('active', 'running') THEN 0 WHEN s.state IN ('retained', 'recoverable') THEN 1 ELSE 2 END, (SELECT max(r.created_at) FROM core_runs AS q JOIN runs AS r ON r.id = q.run_id WHERE q.area_id = s.id) DESC NULLS LAST, s.id DESC LIMIT 1) AND (SELECT s.id FROM core_areas AS s WHERE s.tenant = oa.tenant AND s.home_node = oa.home_node AND s.workspace_id = oa.workspace_id AND s.agent_id = oa.agent_id AND s.owner = oa.owner ORDER BY CASE WHEN s.state IN ('active', 'running') THEN 0 WHEN s.state IN ('retained', 'recoverable') THEN 1 ELSE 2 END, (SELECT max(r.created_at) FROM core_runs AS q JOIN runs AS r ON r.id = q.run_id WHERE q.area_id = s.id) DESC NULLS LAST, s.id DESC LIMIT 1) = (SELECT (SELECT s.id FROM core_areas AS s WHERE s.tenant = a.tenant AND s.home_node = a.home_node AND s.workspace_id = a.workspace_id AND s.agent_id = a.agent_id AND s.owner = a.owner ORDER BY CASE WHEN s.state IN ('active', 'running') THEN 0 WHEN s.state IN ('retained', 'recoverable') THEN 1 ELSE 2 END, (SELECT max(r.created_at) FROM core_runs AS q JOIN runs AS r ON r.id = q.run_id WHERE q.area_id = s.id) DESC NULLS LAST, s.id DESC LIMIT 1) FROM core_areas AS a WHERE a.id = core_runs.area_id) AND (o.area_id, o.sequence) < (core_runs.area_id, core_runs.sequence)) WHERE EXISTS (SELECT 1 FROM core_areas AS a WHERE a.id = core_runs.area_id AND a.id <> (SELECT s.id FROM core_areas AS s WHERE s.tenant = a.tenant AND s.home_node = a.home_node AND s.workspace_id = a.workspace_id AND s.agent_id = a.agent_id AND s.owner = a.owner ORDER BY CASE WHEN s.state IN ('active', 'running') THEN 0 WHEN s.state IN ('retained', 'recoverable') THEN 1 ELSE 2 END, (SELECT max(r.created_at) FROM core_runs AS q JOIN runs AS r ON r.id = q.run_id WHERE q.area_id = s.id) DESC NULLS LAST, s.id DESC LIMIT 1));
UPDATE "core_areas" SET "next_sequence" = (SELECT max(q.sequence) + 1 FROM core_runs AS q WHERE q.area_id = core_areas.id) WHERE (SELECT max(q.sequence) + 1 FROM core_runs AS q WHERE q.area_id = core_areas.id) > "next_sequence";
UPDATE "core_operations" SET "area_id" = (SELECT (SELECT s.id FROM core_areas AS s WHERE s.tenant = a.tenant AND s.home_node = a.home_node AND s.workspace_id = a.workspace_id AND s.agent_id = a.agent_id AND s.owner = a.owner ORDER BY CASE WHEN s.state IN ('active', 'running') THEN 0 WHEN s.state IN ('retained', 'recoverable') THEN 1 ELSE 2 END, (SELECT max(r.created_at) FROM core_runs AS q JOIN runs AS r ON r.id = q.run_id WHERE q.area_id = s.id) DESC NULLS LAST, s.id DESC LIMIT 1) FROM core_areas AS a WHERE a.id = core_operations.area_id) WHERE EXISTS (SELECT 1 FROM core_areas AS a WHERE a.id = core_operations.area_id AND a.id <> (SELECT s.id FROM core_areas AS s WHERE s.tenant = a.tenant AND s.home_node = a.home_node AND s.workspace_id = a.workspace_id AND s.agent_id = a.agent_id AND s.owner = a.owner ORDER BY CASE WHEN s.state IN ('active', 'running') THEN 0 WHEN s.state IN ('retained', 'recoverable') THEN 1 ELSE 2 END, (SELECT max(r.created_at) FROM core_runs AS q JOIN runs AS r ON r.id = q.run_id WHERE q.area_id = s.id) DESC NULLS LAST, s.id DESC LIMIT 1));
