DELETE FROM "core_areas" WHERE core_areas.id <> (SELECT s.id FROM core_areas AS s WHERE s.tenant = core_areas.tenant AND s.home_node = core_areas.home_node AND s.workspace_id = core_areas.workspace_id AND s.agent_id = core_areas.agent_id AND s.owner = core_areas.owner ORDER BY CASE WHEN s.state IN ('active', 'running') THEN 0 WHEN s.state IN ('retained', 'recoverable') THEN 1 ELSE 2 END, (SELECT max(r.created_at) FROM core_runs AS q JOIN runs AS r ON r.id = q.run_id WHERE q.area_id = s.id) DESC NULLS LAST, s.id DESC LIMIT 1);
